section.piece_a:
class RateQuote
  def initialize(client)
    @client = client
  end

  def convert(amount_cents, from:, to:)
    rate = Rails.cache.fetch(["fx-rate", from, to, Time.now.utc.to_date], expires_in: 1.day) do
      @client.rate(from: from, to: to)
    end
    (amount_cents * rate).round
  end
end

